mapper.select:
SELECT b.id, b.title, b.image, b.link_url AS linkUrl, b.position, b.sort, b.status, b.create_time AS createTime, b.update_time AS updateTime FROM banner b WHERE b.deleted = 0
AND b.position = #{q.position}
AND b.status = #{q.status}
AND ( b.title LIKE CONCAT('%', #{q.keyword}, '%') OR b.link_url LIKE CONCAT('%', #{q.keyword}, '%') )
ORDER BY b.position ASC, b.sort ASC, b.id ASC
